define([],function(){'use strict';var ROOT_SELECTOR='[data-region="course-content"], #region-main .course-content, .course-content';var TILE_GLYPHS={material:'▤',quiz:'?',task:'▣',cert:'◈',other:'●'};function el(tag,cls,text){var e=document.createElement(tag);if(cls){e.className=cls;}if(text!=null){e.textContent=text;}return e;}function percentOf(done,total){return total>0?Math.round((done/total)*100):0;}function enhanceActivity(li,cmid,info,strings,nextCmid){if(!li||!info||li.querySelector('.unics-chip')){return;}var grid=li.querySelector('.activity-grid');if(!grid){return;}var item=li.querySelector('.activity-item')||li;var isNext=!!nextCmid&&cmid===nextCmid;li.classList.add('unics-act');li.classList.add('unics-type-'+info.type);if(info.status==='locked'){li.classList.add('unics-locked');}if(isNext){li.classList.add('unics-next');}var tile=el('span','unics-tile',TILE_GLYPHS[info.type]||TILE_GLYPHS.other);tile.setAttribute('aria-hidden','true');grid.insertBefore(tile,grid.firstChild);var nameArea=li.querySelector('.activity-name-area')||grid;var subText=info.sub?(info.typeLabel+' - '+info.sub):info.typeLabel;if(subText){nameArea.appendChild(el('div','unics-act-sub',subText));}var chipKey=(isNext&&info.status==='todo')?'continue':info.status;grid.appendChild(el('span','unics-chip unics-chip-'+chipKey,strings[chipKey]||''));if(info.status==='locked'&&info.lockWhy){item.appendChild(el('p','unics-lock-why',info.lockWhy));}}function renderSectionProgress(li,secData,strings){if(!li||!secData||li.querySelector('.unics-sec-progress')){return;}var done=secData.done||0;var total=secData.total||0;var wrap=el('div','unics-sec-progress');if(secData.complete){wrap.classList.add('unics-sec-progress-done');if(strings.themeDone){wrap.appendChild(el('span','unics-sec-done',strings.themeDone));}}else{wrap.setAttribute('role','progressbar');wrap.setAttribute('aria-valuenow',String(done));wrap.setAttribute('aria-valuemin','0');wrap.setAttribute('aria-valuemax',String(total));if(secData.aria){wrap.setAttribute('aria-valuetext',secData.aria);}wrap.appendChild(el('div','unics-sec-progress-bar')).style.width=percentOf(done,total)+'%';wrap.appendChild(el('span','unics-sec-progress-label',secData.label||(done+'/'+total)));}var badges=li.querySelector('[data-region="sectionbadges"]');if(badges){badges.appendChild(wrap);return;}var header=li.querySelector('.course-section-header');if(header&&header.parentNode){header.parentNode.insertBefore(wrap,header.nextSibling);}}function renderCourseHeader(data){if(document.querySelector('.unics-course-head')){return;}var root=document.querySelector(ROOT_SELECTOR);if(!root||!root.parentNode){return;}var course=data.course||{};var strings=data.strings||{};var done=course.done||0;var total=course.total||0;var head=el('div','unics-course-head');var bar=el('div','unics-course-progress');bar.setAttribute('role','progressbar');bar.setAttribute('aria-valuenow',String(done));bar.setAttribute('aria-valuemin','0');bar.setAttribute('aria-valuemax',String(total));if(course.label){bar.setAttribute('aria-valuetext',course.label);}bar.appendChild(el('div','unics-course-progress-bar')).style.width=percentOf(done,total)+'%';head.appendChild(bar);if(course.label){head.appendChild(el('p','unics-course-progress-label',course.label));}if(course.encourage){head.appendChild(el('p','unics-course-encourage',course.encourage));}if(data.next&&data.next.cmid){var link=document.querySelector('#module-'+data.next.cmid+' .aalink')||document.querySelector('#module-'+data.next.cmid+' .activityname a');if(link&&link.href){var cta=el('a','unics-cta',data.next.label||strings.continue||'');cta.href=link.href;head.appendChild(cta);}}else if(total>0&&done===total&&strings.courseDone){head.appendChild(el('p','unics-course-done',strings.courseDone));}root.parentNode.insertBefore(head,root);}return{init:function(data){try{data=data||{};var root=document.querySelector(ROOT_SELECTOR);if(!root){return;}document.body.classList.add('unics-child-course');renderCourseHeader(data);var cms=data.cms||{};var nextCmid=(data.next&&data.next.cmid)?data.next.cmid:null;Object.keys(cms).forEach(function(cmid){var li=document.getElementById('module-'+cmid);if(li){enhanceActivity(li,parseInt(cmid,10),cms[cmid],data.strings||{},nextCmid);}});var sections=data.sections||{};Object.keys(sections).forEach(function(num){var sec=document.getElementById('section-'+num);if(sec){renderSectionProgress(sec,sections[num],data.strings||{});}});}catch(e){if(window.console){console.warn('unics course_child',e);}}}};});
